vol=R.std(0)
cands['all_trend_iv']={n:float(1/vol[i]) for i,n in enumerate(names) if not n.startswith('hold')}
# train min-variance-ish: ridge mean-variance on train
idx=[i for i,n in enumerate(names)]
X=R.astype(float); mu=X.mean(0); C=np.cov(X.T)
w=np.linalg.solve(C+np.eye(len(mu))*np.trace(C)/len(mu)*1.0, mu)
cands['mv_ridge_train']={names[i]:float(w[i]) for i in range(len(names))}
for k,v in cands.items():
    wv=np.array([v.get(n,0) for n in names]); 
    print(k, round(sh(X@wv),3), bt.backtest(v))
